2. Initialize the sequence with the correct first three numbers (0, -1, -1).
3. Use an iterative approach instead of recursion for efficiency.

Here is the corrected program:

```cpp
#include <iostream>
#include <vector>
using namespace std;

// Function to find the nth number in the sequence
int find_nth_number(int n) {
    if (n == 1) return 0;
    if (n == 2 || n == 3) return -1;

    vector<int> sequence = {0, -1, -1};
    for (int i = 3; i < n; ++i) {
        sequence.push_back(sequence[i - 1] + sequence[i - 2] + sequence[i - 3]);
    }

    return sequence[n - 1];
}

int main() {
    int n;
    cout << "Enter the value of n: ";
    cin >> n;

    int result = find_nth_number(n);
    cout << "The " << n << "th number in the sequence is: " << result << endl;

    return 0;
}
```

